// --- LIBRARIES --- //
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>

// --- DEFINING CONSTANTS --- //
#define SCREEN_W 320
#define SCREEN_H 240
#define KEY_BASE 0xFF200050
#define SW_BASE 0xFF200040
#define PS2_BASE 0xFF200100
#define LED_BASE 0xFF200000

// Window boundaries
#define WINDOW_START_X 24
#define WINDOW_END_X 294
#define WINDOW_START_Y 39
#define WINDOW_END_Y 175

// Player drawing parameters
#define DEFAULT_PLAYER_RADIUS 15
#define DEFAULT_SHOOT_RADIUS 7

// --- GLOBAL VARIABLES --- //
volatile bool gameEnd = false;
volatile bool eventFlag = false;
volatile int restart_flag = 0;

volatile int roundNumber = 0;
volatile int player1totalscore = 0;
volatile int player2totalscore = 0;

volatile int pixel_buffer_start;
short int Buffer1[240][512];  // 240 rows, 512 (320 + padding) columns
short int Buffer2[240][512];

volatile int* LEDR_ptr = (int*)0xFF200000;
volatile int* HEX3_HEX0_ptr = (int*)0xFF200020;
volatile int* HEX5_HEX4_ptr = (int*)0xFF200030;
char bit_codes[] = {0x3f, 0x06, 0x5b, 0x4f, 0x66, 0x6d, 0x7d, 0x07, 0x7f, 0x67};

// audio global variables 
int beepFlag = 0; 

// --- STRUCTS --- //
struct player {
  int x;
  int y;
  int old_x;
  int old_y;

  int dx;
  int dy;
  int colour;
  int paint_colour;

  int score;

  int player_radius;
  int shoot_radius;

  int shoot_cooldown;
  int shoot_cooldown_value;
};

// --- FUNCTION HEADERS --- //

// Drawing Functions
volatile int pixel_buffer_start;
void plot_pixel(int x, int y, short int line_colour, short* back_buf_ptr);
void wait_for_vsync(void);
void draw_background(short* back_buf_ptr);
void updateProgressBar(short* back_buf_ptr);

// Player functions
void read_ps2key(struct player* p1, struct player* p2, short* back_buf_ptr);
void update_player_position(struct player* p);
void update_player_movement(struct player* p, int new_dx, int new_dy);
void read_keyboard_input(struct player* p);
void shoot(struct player* p, short* back_buf_ptr);
void read_switch_input(short* back_buf_ptr);
void safe_plot_pixel(int x, int y, short int colour, short* back_buf_ptr);
void draw_player(struct player* p, short* back_buf_ptr);

// Background restore functions
void restore_background_area(int x_min, int x_max, int y_min, int y_max,
                             short* back_buf_ptr);
void restore_old_player_area(struct player* p, short* back_buf_ptr);
void clearProgressBar(short* back_buf_ptr);

// Random Events
void clearPaintEvent(short* back_buf_ptr);

// Area calculation
void draw_digit(int x, int y, int digit, short color, short* buf);
void displayScore(struct player* p1, struct player* p2, short* back_buf_ptr);
void calculateArea(struct player* p);

void read_ps2key(struct player* p1, struct player* p2, short* back_buf_ptr);
void restart(short* back_buf_ptr, struct player* p1, struct player* p2);

// --- DRAWING FUNCTIONS --- //
// Plot single pixel
void plot_pixel(int x, int y, short int line_colour, short* back_buf_ptr) {
  volatile short int* one_pixel_address;
  // y << 9 is because it is padded
  one_pixel_address = back_buf_ptr + (y << 9) + x;
  *one_pixel_address = line_colour;
}

// Double buffering sync
void wait_for_vsync(void) {
  volatile int* pixel_ctrl_ptr = (int*)0xFF203020;
  volatile int* status_ptr = pixel_ctrl_ptr + 3;

  *pixel_ctrl_ptr =
      1;  // write 1 to Buffer register (offset +0) to trigger swap

  while ((*status_ptr & 0x1) != 0);
}

// Draw background
void draw_background(short* back_buf_ptr) {
  for (int y = 0; y < SCREEN_H; y++) {
    for (int x = 0; x < SCREEN_W; x++) {
      plot_pixel(x, y, background[y * SCREEN_W + x], back_buf_ptr);
    }
  }
}

// Draw progress bar
// The progress goes from 77 to 242, 242 - 77 = 165
volatile double progressx = 77;

void updateProgressBar(short* back_buf_ptr) {
  if (progressx < 242) {
    for (int y = 0; y < 10; y++) {
      plot_pixel(progressx, 194 + y, 0x3130, back_buf_ptr);
    }
  }
}

// --- PLAYER FUNCTIONS --- //
void update_player_position(struct player* p) {
  // shoot timer decreaser
  if (p->shoot_cooldown > 0) {
    p->shoot_cooldown--;
  }

  // Save old position before updating
  p->old_x = p->x;
  p->old_y = p->y;

  p->x += p->dx;
  p->y += p->dy;

  // Clamp position to window bounds
  if (p->x < WINDOW_START_X) {
    p->x = WINDOW_START_X;
  } else if (p->x > WINDOW_END_X) {
    p->x = WINDOW_END_X;
  }

  if (p->y < WINDOW_START_Y) {
    p->y = WINDOW_START_Y;
  } else if (p->y > WINDOW_END_Y) {
    p->y = WINDOW_END_Y;
  }
}

void update_player_movement(struct player* p, int new_dx, int new_dy) {
  p->dx = new_dx;
  p->dy = new_dy;
}

void read_keyboard_input(struct player* p) {
  volatile int* key_ptr = (int*)KEY_BASE;
  int key_value = *key_ptr;

  // Check which key is pressed (bits 0-3 represent keys 0-3)
  if (key_value & 0x1) {  // Key 0 pressed - move right
    update_player_movement(p, 1, 0);
  } else if (key_value & 0x2) {  // Key 1 pressed - move left
    update_player_movement(p, -1, 0);
  } else if (key_value & 0x4) {  // Key 2 pressed - move down
    update_player_movement(p, 0, 1);
  } else if (key_value & 0x8) {  // Key 3 pressed - move up
    update_player_movement(p, 0, -1);
  } else {  // No key pressed - stop
    update_player_movement(p, 0, 0);
  }
}

// Maybe change the shape to like a random splotter in the future, but for now
// just a solid circle
void shoot(struct player* p, short* back_buf_ptr) {
  if (p->shoot_cooldown > 0) {
    return;
  }

  for (int dy = -(p->shoot_radius); dy <= (p->shoot_radius); dy++) {
    for (int dx = -(p->shoot_radius); dx <= (p->shoot_radius); dx++) {
      if (dx * dx + dy * dy <= (p->shoot_radius) * (p->shoot_radius)) {
        int px = p->x + dx;
        int py = p->y + dy;

        // Check bounds (window bounds) and color both screen and background
        if (px >= WINDOW_START_X && px <= WINDOW_END_X &&
            py >= WINDOW_START_Y && py <= WINDOW_END_Y) {
          plot_pixel(px, py, p->colour, back_buf_ptr);
          background[py * SCREEN_W + px] = p->paint_colour;
        }
      }
    }
  }

  p->shoot_cooldown = p->shoot_cooldown_value;
}

void safe_plot_pixel(int x, int y, short int colour, short* back_buf_ptr) {
  // Check bounds within the window
  if (x >= WINDOW_START_X && x <= WINDOW_END_X && y >= WINDOW_START_Y &&
      y <= WINDOW_END_Y) {
    plot_pixel(x, y, colour, back_buf_ptr);
  }
}

void draw_player(struct player* p, short* back_buf_ptr) {
  int size = (p->player_radius) - 5;
  int thickness = 2;
  short int colour = p->colour;

  // Draw vertical line (crosshair vertical bar)
  for (int i = -size; i <= size; i++) {
    for (int t = 0; t < thickness; t++) {
      safe_plot_pixel(p->x + t, p->y + i, 0, back_buf_ptr);
    }
  }

  // Draw horizontal line (crosshair horizontal bar)
  for (int i = -size; i <= size; i++) {
    for (int t = 0; t < thickness; t++) {
      safe_plot_pixel(p->x + i, p->y + t, 0, back_buf_ptr);
    }
  }

  // Draw circle using midpoint circle algorithm
  int x = 0;
  int y = p->player_radius;
  int d = 3 - 2 * p->player_radius;  // decision parameter

  while (x <= y) {
    // Draw 8 symmetric points with bounds checking
    for (int t = 0; t < thickness; t++) {
      safe_plot_pixel(p->x + x + t, p->y + y, colour, back_buf_ptr);
      safe_plot_pixel(p->x - x + t, p->y + y, colour, back_buf_ptr);
      safe_plot_pixel(p->x + x + t, p->y - y, colour, back_buf_ptr);
      safe_plot_pixel(p->x - x + t, p->y - y, colour, back_buf_ptr);
      safe_plot_pixel(p->x + y + t, p->y + x, colour, back_buf_ptr);
      safe_plot_pixel(p->x - y + t, p->y + x, colour, back_buf_ptr);
      safe_plot_pixel(p->x + y + t, p->y - x, colour, back_buf_ptr);
      safe_plot_pixel(p->x - y + t, p->y - x, colour, back_buf_ptr);
    }

    if (d < 0) {
      d = d + 4 * x + 6;
    } else {
      d = d + 4 * (x - y) + 10;
      y--;
    }
    x++;
  }
}

// --- BACKGROUND RESTORE FUNCTIONS --- //
void restore_background_area(int x_min, int x_max, int y_min, int y_max,
                             short* back_buf_ptr) {
  // Clamp to window bounds
  if (x_min < WINDOW_START_X) {
    x_min = WINDOW_START_X;
  }
  if (x_max > WINDOW_END_X) {
    x_max = WINDOW_END_X;
  }
  if (y_min < WINDOW_START_Y) {
    y_min = WINDOW_START_Y;
  }
  if (y_max > WINDOW_END_Y) {
    y_max = WINDOW_END_Y;
  }

  for (int y = y_min; y <= y_max; y++) {
    for (int x = x_min; x <= x_max; x++) {
      plot_pixel(x, y, background[y * SCREEN_W + x], back_buf_ptr);
    }
  }
}

// this resets a square of where the player was to the background colour
// kinda naive but like lazy method and fast enough
void restore_old_player_area(struct player* p, short* back_buf_ptr) {
  int size = (p->player_radius) + 15 + 2;  // radius + crosshair + thickness
  int x_min = p->old_x - size;
  int x_max = p->old_x + size;
  int y_min = p->old_y - size;
  int y_max = p->old_y + size;

  restore_background_area(x_min, x_max, y_min, y_max, back_buf_ptr);
}

