  wait_for_vsync();
  pixel_buffer_start = *(pixel_ctrl_ptr + 1);

  clearPaintEvent((short*)pixel_buffer_start);
  clearProgressBar((short*)pixel_buffer_start);
  draw_background((short*)pixel_buffer_start);

  progressx = 77;
