//-------------------------Key Inturupt Stuff-------------------------//
static void handler(void) __attribute__((interrupt("machine")));
void set_KEY(void);
void KEY_ISR(void);
void init_interrupts(void);
#define LEDR_BASE 0xFF200000

void setup_interrupts(void) {
  int mstatus_value, mtvec_value, mie_value;

  /* Disable global interrupts */
  mstatus_value = 0b1000;
  __asm__ volatile("csrc mstatus, %0" ::"r"(mstatus_value));

  /* Set trap handler */
  mtvec_value = (int)&handler;
  __asm__ volatile("csrw mtvec, %0" ::"r"(mtvec_value));

  /* Disable all interrupt sources */
  __asm__ volatile("csrr %0, mie" : "=r"(mie_value));
  __asm__ volatile("csrc mie, %0" ::"r"(mie_value));

  /* Enable KEY interrupt only */
  mie_value = 0x40000;
  __asm__ volatile("csrs mie, %0" ::"r"(mie_value));

  /* Enable global interrupts */
  __asm__ volatile("csrs mstatus, %0" ::"r"(mstatus_value));
}

void handler(void) {
  int mcause_value;
  __asm__ volatile("csrr %0, mcause" : "=r"(mcause_value));

  if (mcause_value == 0x80000012) {
    KEY_ISR();
  }
}

void set_KEY(void) {
  volatile int* KEY_ptr = (int*)KEY_BASE;

  *(KEY_ptr + 3) = 0xF;  // clear EdgeCapture
  *(KEY_ptr + 2) = 0x1;  // enable KEY0 interrupt
}

void KEY_ISR(void) {
  volatile int* KEY_ptr = (int*)KEY_BASE;
  volatile int* LEDR_ptr = (int*)LEDR_BASE;
  int pressed;

  pressed = *(KEY_ptr + 3);  // EdgeCapture
  *(KEY_ptr + 3) = pressed;  // clear

  if (pressed & 0x1) {  // KEY0
    *LEDR_ptr ^= 0x2;
    restart_flag = 1;
    beepFlag = 0; 
  }
}

//--------------------------------------------------------

void read_ps2key(struct player* p1, struct player* p2, short* back_buf_ptr) {
  volatile int* PS2_ptr = (int*)PS2_BASE;

  static int got_f0 = 0;

  while (1) {
    int data = *PS2_ptr;
    int rvalid = (data >> 15) & 0x1;

    if (!rvalid) break;

    unsigned char byte = data & 0xFF;

    if (byte == 0xF0) {
      got_f0 = 1;  // key release
    } else {
      if (got_f0) {
        got_f0 = 0;  // ignore release
      } else {
        switch (byte) {
          // player 1  ------------------
          case 0x1D:  // W, move up
            update_player_movement(p1, 0, -1);
            break;

          case 0x1B:  // S, move down
            update_player_movement(p1, 0, 1);
            break;

          case 0x1C:  // A, move left
            update_player_movement(p1, -1, 0);
            break;

          case 0x23:  // D, move right
            update_player_movement(p1, 1, 0);
            break;

          case 0x21:  // C, shoot
            shoot(p1, back_buf_ptr);
            break;

          // player 2  ------------------
          case 0x43:  // I, move up
            update_player_movement(p2, 0, -1);
            break;

          case 0x3B:  // J, move left
            update_player_movement(p2, -1, 0);
            break;

          case 0x42:  // K, move down
            update_player_movement(p2, 0, 1);
            break;

          case 0x4B:  // L, move right
            update_player_movement(p2, 1, 0);
            break;

          case 0x31:  // N, shoot
            shoot(p2, back_buf_ptr);
            break;

          default:
            break;
        }
      }
    }
  }
}

// --- AUDIO --- //

// Make a beep sound when the progress bar is almost up
// 1000Hz frequency beep 1000 samples/s
// 2000Hz frequency beep
// audio is sampled at 8 kHz 8000 samples/s

// samples per cycle = 8000/1000 = 8 samples
// will set max amplitude to 2000 
volatile int*audio_ptr = (int*)0xff203040; 

const int sine_beep[8] = {
     0, 14142, 20000, 14142,
     0,-14142,-20000,-14142
};

// need to feed empty samples to the audio FIFO until a beep is triggered 
// global variables to keep track of when to trigger beeps, etc. 

int beepSignal = 0; // whether or not a beep is triggered 
int beepSamplesLeft = 0; 
int beepSampleIndex = 0;



/*
void play_beep(){
    volatile int*audio_ptr = (int*)0xff203040; 
    int num_samples = 800; 

    int fifospace; 
    fifospace = *(audio_ptr +1); 

    for (int i = 0; i < num_samples; i++){
        if ((fifospace && 0X00FF0000) > 0){
            *(audio_ptr + 2) = sine_beep[i]; 
            *(audio_ptr + 3) = sine_beep[i]; 
        }
    }

}*/

void run_audio(){ 
    int fifospace = *(audio_ptr + 1); 

    int output = 0;
    
    while ((fifospace & 0X00FF0000) > 0 ){
        // if a beep is triggered and it is not done going through all the samples yet
        // then make the output the sine signal output
        if (beepSignal && (beepSamplesLeft > 0)){
            output = sine_beep[beepSampleIndex]; 
            beepSampleIndex = (beepSampleIndex + 1) & 7; // increment beep sample index but also keep it within range
            beepSamplesLeft --; 

            // turn beep signal off when there are no more samples left
            if (beepSamplesLeft == 0){
            beepSignal = 0; 
            }
        }
        else{
            // otherwise feed the audio output no noise
            output = 0; 
        }
        

        *(audio_ptr + 2) = output << 16; 
        *(audio_ptr + 3) = output << 16; 

        // update fiforead 
        fifospace = *(audio_ptr + 1); 

    }
}

void play_beep(){ 
    // turn beep signal on
    beepSignal = 1; 
    beepSamplesLeft = 800; // fill full samples 
    beepSampleIndex = 0; // start index from beginning
}





// --- MAIN PROGRAM -- //
int main(void) {
  // --- Graphics --- //
  // pixel controller holds the front buffer, back buffer, swap bits
  // pixel buffer start holds the image that is displayed
  volatile int* pixel_ctrl_ptr = (int*)0xFF203020;
  pixel_buffer_start = *pixel_ctrl_ptr;

  // Set back pixel buffer to buffer 1 and then swap so that it is at the front
  *(pixel_ctrl_ptr + 1) = (int)&Buffer1;
  wait_for_vsync();

  // Set back buffer to buffer 2
  short* back_buf_ptr = (short*)*(pixel_ctrl_ptr + 1);
  *(pixel_ctrl_ptr + 1) = (int)&Buffer2;
  pixel_buffer_start = *(pixel_ctrl_ptr + 1);
  back_buf_ptr = (short*)pixel_buffer_start;
  draw_background(back_buf_ptr);  // draw background onto back buffer
  wait_for_vsync();               // swap to display to front

  // set back buffer to buffer 1
  pixel_buffer_start = *(pixel_ctrl_ptr + 1);
  back_buf_ptr = (short*)pixel_buffer_start;
  draw_background(back_buf_ptr);  // draw background on buffer 1

  // --- Set up players --- //

  // x   y  old_x old_y dx dy colour score player_radius, shoot_radius
  struct player p1 = {160,    120, 160, 120, 1, 0, 0xF800,
                      0xF800, 0,   15,  7,   0, 30};
  struct player p2 = {100,    100, 100, 100, 0, 1, 0x001F,
                      0x001F, 0,   15,  7,   0, 30};

  set_KEY();
  setup_interrupts();

  volatile int* LEDR_ptr = (int*)0xFF200000;

  *HEX3_HEX0_ptr = bit_codes[player2totalscore];
  *HEX5_HEX4_ptr = (bit_codes[player1totalscore] << 8);

  // -- set up audio register -- //
  *(audio_ptr) = 0x8;  // clear the output FIFOs
  *(audio_ptr) = 0x0;  // resume input conversion

// --- MAIN GAME LOOP --- //
game_loop:
  while (!gameEnd) {
    if (restart_flag) {
      restart(back_buf_ptr, &p1, &p2);
      restart_flag = 0;
    }

    // --- AUDIO OUTPUT STUFF --- //

    // -------------------------- //

    if (progressx >= 230 && (beepFlag == 0)){ 
        play_beep(); 
        beepFlag = 1; 
    }

    // If the game is over light up an LED
    if (progressx >= 242) {
      *LEDR_ptr |= 0x1;  // light up LED0 to indicate end of round

      roundNumber += 1;
      // printf("round %d done\n", roundNumber);

      // increment total player score
      if (p1.score > p2.score) {
        // printf("player1 wins this round\n");
        player1totalscore += 1;
      } else if (p2.score > p1.score) {
        // printf("player2 wins this round\n");
        player2totalscore += 1;
      }

      if (roundNumber < 3) {
        *HEX3_HEX0_ptr = bit_codes[player2totalscore];
        *HEX5_HEX4_ptr = (bit_codes[player1totalscore] << 8);

        // printf("next round\n");
        restart(back_buf_ptr, &p1, &p2);

      }

      // End game after 3 rounds
      else {
        gameEnd = true;
      }
    }

    // --- RANDOM EVENTS --- //

    // 0 - clear paint
    // 1 - increase paint brush size
    // 2 - decrease paint brush size
    // 3 - increase player cooldown
    // 4 - decrease player cooldown
    // 5 - swap player colours

    // Sprite Window Dimensions

    // Events that affect all players/entire game state is drawn in the top
    // right corner
    int topEventWindowx = 255;
    int topEventWindowy = 9;

    // Events that affect individual players are drawn in the player boxes
    int player1windowx = 7;
    int player2windowx = 250;
    int playerwindowy = 203;

    // TRIGGER RANDOM EVENT
    if (progressx >= 160 && eventFlag == false) {
      // raise flag
      eventFlag = true;
      // run random event
      int randomEvent = chooseRandomEvent();
      // printf("%d random event number\n", randomEvent);
      *LEDR_ptr = (1 << 9);
      int playerAffected = chooseRandomPlayer();
        printf("%d player affect\n", playerAffected);

      // CLEAR PAINT EVENT
      if (randomEvent == 0) {
        // run clear paint event
        clearPaintEvent(back_buf_ptr);
        wait_for_vsync();
        pixel_buffer_start = *(pixel_ctrl_ptr + 1);
        clearPaintEvent(pixel_buffer_start);

        // draw clear paint event sprite
        for (int y = 0; y < 25; y++) {
          for (int x = 0; x < 60; x++) {
            plot_pixel(topEventWindowx + x, topEventWindowy + y,
                       clearcanvassprite[y * 60 + x], pixel_buffer_start);
            plot_pixel(topEventWindowx + x, topEventWindowy + y,
                       clearcanvassprite[y * 60 + x], back_buf_ptr);
          }
        }

        wait_for_vsync();
        pixel_buffer_start = *(pixel_ctrl_ptr + 1);

        for (int y = 0; y < 25; y++) {
          for (int x = 0; x < 60; x++) {
            plot_pixel(topEventWindowx + x, topEventWindowy + y,
                       clearcanvassprite[y * 60 + x], pixel_buffer_start);
            plot_pixel(topEventWindowx + x, topEventWindowy + y,
                       clearcanvassprite[y * 60 + x], back_buf_ptr);
          }
        }
      }

      // INCREASE PAINT SIZE
      if (randomEvent == 1) {
        // Run increase paint size event
        int playerAffected = chooseRandomPlayer();
        printf("%d player affect\n", playerAffected);
        increasePaintbrush(&p1, &p2, playerAffected);

        int playerWindowX = player1windowx;

        if (playerAffected == 2) {
          playerWindowX = player2windowx;
        }

        // draw increasePaintbrush event sprite
        for (int y = 0; y < 30; y++) {
          for (int x = 0; x < 60; x++) {
            plot_pixel(playerWindowX + x, playerwindowy + y,
                       sizeupsprite[y * 60 + x], pixel_buffer_start);
            plot_pixel(playerWindowX + x, playerwindowy + y,
                       sizeupsprite[y * 60 + x], back_buf_ptr);
          }
        }

        wait_for_vsync();
        pixel_buffer_start = *(pixel_ctrl_ptr + 1);

        for (int y = 0; y < 30; y++) {
          for (int x = 0; x < 60; x++) {
            plot_pixel(playerWindowX + x, playerwindowy + y,
                       sizeupsprite[y * 60 + x], pixel_buffer_start);
            plot_pixel(playerWindowX + x, playerwindowy + y,
                       sizeupsprite[y * 60 + x], back_buf_ptr);
          }
        }
      }

      // DECREASE PAINT SIZE
      if (randomEvent == 2) {
        // Run decrease paint size event
        int playerAffected = chooseRandomPlayer();
        printf("%d player affect\n", playerAffected);
        decreasePaintbrush(&p1, &p2, playerAffected);

        int playerWindowX = player1windowx;

        if (playerAffected == 2) {
          playerWindowX = player2windowx;
        }

        // draw decreasePaintbrush event sprite
        for (int y = 0; y < 30; y++) {
          for (int x = 0; x < 60; x++) {
            plot_pixel(playerWindowX + x, playerwindowy + y,
                       sizedownsprite[y * 60 + x], pixel_buffer_start);
            plot_pixel(playerWindowX + x, playerwindowy + y,
                       sizedownsprite[y * 60 + x], back_buf_ptr);
          }
        }

        wait_for_vsync();
        pixel_buffer_start = *(pixel_ctrl_ptr + 1);

        for (int y = 0; y < 30; y++) {
          for (int x = 0; x < 60; x++) {
            plot_pixel(playerWindowX + x, playerwindowy + y,
                       sizedownsprite[y * 60 + x], pixel_buffer_start);
            plot_pixel(playerWindowX + x, playerwindowy + y,
                       sizedownsprite[y * 60 + x], back_buf_ptr);
          }
        }
      }

      if (randomEvent == 3) {
        swapPlayerColours(&p1, &p2);

        for (int y = 0; y < 25; y++) {
          for (int x = 0; x < 60; x++) {
            plot_pixel(topEventWindowx + x, topEventWindowy + y,
                       swapsprite[y * 60 + x], pixel_buffer_start);
            plot_pixel(topEventWindowx + x, topEventWindowy + y,
                       swapsprite[y * 60 + x], back_buf_ptr);
          }
        }

        wait_for_vsync();
        pixel_buffer_start = *(pixel_ctrl_ptr + 1);

        for (int y = 0; y < 25; y++) {
          for (int x = 0; x < 60; x++) {
            plot_pixel(topEventWindowx + x, topEventWindowy + y,
                       swapsprite[y * 60 + x], pixel_buffer_start);
            plot_pixel(topEventWindowx + x, topEventWindowy + y,
                       swapsprite[y * 60 + x], back_buf_ptr);
          }
        }
      }
    }
    // --------------------- //

    // --- RUN AUDIO --- //
    run_audio();

    // --- PLAYER UPDATES --- //

    volatile int* sw_ptr = (int*)SW_BASE;
    int sw_value = *sw_ptr;
    // Update player scores

    // handle controls
    read_ps2key(&p1, &p2, back_buf_ptr);

    // Update positions (old positions are saved inside update_player_position)
    update_player_position(&p1);
    update_player_position(&p2);

    // Restore background where players WERE (old positions)
    restore_old_player_area(&p1, back_buf_ptr);
    restore_old_player_area(&p2, back_buf_ptr);

    displayScore(&p1, &p2, back_buf_ptr);

    // Draw players at NEW positions
    draw_player(&p1, back_buf_ptr);
    draw_player(&p2, back_buf_ptr);

    // Update progress bar
    progressx = progressx + 0.5;
    updateProgressBar(back_buf_ptr);

    // Wait for vertical sync and swap buffers
    wait_for_vsync();
    pixel_buffer_start = *(pixel_ctrl_ptr + 1);
    back_buf_ptr = (short*)*(pixel_ctrl_ptr + 1);
  }

  // Game End test
  // Add  game end screen after a few rounds
  int player1area = p1.score;
  int player2area = p2.score;

  *HEX3_HEX0_ptr = bit_codes[player2totalscore];
  *HEX5_HEX4_ptr = (bit_codes[player1totalscore] << 8);

  if (player1totalscore > player2totalscore) {
    *LEDR_ptr = 0b100000000;
    for (int y = 0; y < 138; y++) {
      for (int x = 0; x < 272; x++) {
        plot_pixel(23 + x, 38 + y, player1end[y * 272 + x], pixel_buffer_start);
        plot_pixel(23 + x, 38 + y, player1end[y * 272 + x], back_buf_ptr);
      }
    }
  } else if (player2totalscore > player1totalscore) {
    for (int y = 0; y < 138; y++) {
      for (int x = 0; x < 272; x++) {
        plot_pixel(23 + x, 38 + y, player2end[y * 272 + x], pixel_buffer_start);
        plot_pixel(23 + x, 38 + y, player2end[y * 272 + x], back_buf_ptr);
      }
    }
  } else {
    for (int y = 0; y < 138; y++) {
      for (int x = 0; x < 272; x++) {
        plot_pixel(23 + x, 38 + y, tiegameend[y * 272 + x], pixel_buffer_start);
        plot_pixel(23 + x, 38 + y, tiegameend[y * 272 + x], back_buf_ptr);
      }
    }
  }

  wait_for_vsync();
  pixel_buffer_start = *(pixel_ctrl_ptr + 1);
  back_buf_ptr = (short*)*(pixel_ctrl_ptr + 1);


  while (true) {
    if (restart_flag) {
      // gameEnd = false;
      truereset(back_buf_ptr);
      *HEX3_HEX0_ptr = bit_codes[player2totalscore];
      *HEX5_HEX4_ptr = (bit_codes[player1totalscore] << 8);
      goto game_loop;
    }
  }
}
